import math
from collections.abc import Iterable, Mapping
from copy import deepcopy
from numbers import Real


class OfferDirectory:
    _fields = {"id", "code", "starts_at", "ends_at", "discount", "active", "metadata"}

    def __init__(self, offers):
        if isinstance(offers, (str, bytes)) or not isinstance(offers, Iterable):
            raise TypeError("offers must be a non-string iterable")
        prepared = {}
        for offer in offers:
            normalized = self._validate(offer)
            offer_id = normalized["id"]
            if offer_id in prepared:
                raise ValueError("offer ids must be unique")
            prepared[offer_id] = normalized
        self._offers = prepared

    @classmethod
    def _validate(cls, offer):
        if not isinstance(offer, Mapping):
            raise TypeError("each offer must be a mapping")
        if set(offer) != cls._fields:
            raise ValueError("offer fields do not match the schema")
        value = deepcopy(dict(offer))
        offer_id = value["id"]
        if isinstance(offer_id, bool) or not isinstance(offer_id, int):
            raise TypeError("id must be an integer")
        if offer_id <= 0:
            raise ValueError("id must be positive")
        if not isinstance(value["code"], str):
            raise TypeError("code must be a string")
        if not value["code"]:
            raise ValueError("code must not be empty")
        for key in ("starts_at", "ends_at"):
            if isinstance(value[key], bool) or not isinstance(value[key], int):
                raise TypeError(f"{key} must be an integer")
        if value["starts_at"] > value["ends_at"]:
            raise ValueError("starts_at must not exceed ends_at")
        discount = value["discount"]
        if isinstance(discount, bool) or not isinstance(discount, Real):
            raise TypeError("discount must be a real number")
        if not math.isfinite(discount) or not 0 <= discount <= 100:
            raise ValueError("discount must be finite and between 0 and 100")
        if not isinstance(value["active"], bool):
            raise TypeError("active must be boolean")
        if not isinstance(value["metadata"], dict):
            raise TypeError("metadata must be a dictionary")
        return value

    def all_offers(self):
        return [deepcopy(self._offers[key]) for key in sorted(self._offers)]

    def get_offer(self, offer_id):
        if isinstance(offer_id, bool) or not isinstance(offer_id, int):
            raise TypeError("offer_id must be an integer")
        offer = self._offers.get(offer_id)
        return offer

